<?php use App\Core\Security; ?><div class="d-flex justify-content-between mb-3"><h4>گردش کار قیمت</h4><form method="post" action="/pricing/public/workflow/start" class="d-flex gap-2"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input name="product_id" type="number" class="form-control" placeholder="شناسه محصول" required><select name="step_id" class="form-select"><?php foreach($steps as $s):?><option value="<?=$s['id']?>"><?=Security::e($s['name'])?></option><?php endforeach;?></select><select name="assigned_to" class="form-select"><option value="0">بدون مسئول</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=Security::e($u['name'])?></option><?php endforeach;?></select><button class="btn btn-primary">شروع</button></form></div><table class="table table-bordered"><thead><tr><th>کد</th><th>محصول</th><th>مرحله</th><th>وضعیت</th><th>مسئول</th><th>نظر</th><th>عملیات</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=Security::e($r['product_code'])?></td><td><?=Security::e($r['product_name'])?></td><td><?=Security::e($r['step_name'])?></td><td><?=Security::e($r['workflow_status'])?></td><td><?=Security::e($r['assigned_name'])?></td><td><?=Security::e($r['comment'])?></td><td><?php if($r['workflow_id']):?><form method="post" action="/pricing/public/workflow/<?=$r['workflow_id']?>" class="d-flex gap-1"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input name="comment" class="form-control form-control-sm" placeholder="نظر"><select name="status" class="form-select form-select-sm"><option value="completed">تکمیل</option><option value="rejected">رد</option><option value="revision">اصلاح</option></select><button class="btn btn-sm btn-outline-primary">ثبت</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table>